/**
 * After `expo export`: marks the web app's HTML as generated by NexaHeart (the software credit is
 * an additional term of the license, see NOTICE). Usage: node scripts/web-credit.mjs
 */
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const file = join(dirname(fileURLToPath(import.meta.url)), '..', 'dist', 'index.html');
const meta = '<meta name="generator" content="NexaHeart (https://nexaheart.com)">';
const html = await readFile(file, 'utf8');
if (!html.includes(meta)) await writeFile(file, html.replace('<head>', `<head>${meta}`));
